// slide-01.js — Cover Page
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'cover',
  index: 1,
  title: 'Global Renewable Energy in 2025: How Far Have We Come?'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Right side decorative block
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.2, y: 0, w: 3.8, h: 5.625,
    fill: { color: theme.accent }
  });

  // Top accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 0.4, w: 1.2, h: 0.06,
    fill: { color: theme.light }
  });

  // Main title
  slide.addText("Global Renewable\nEnergy in 2025", {
    x: 0.5, y: 0.7, w: 5.4, h: 2.2,
    fontSize: 44, fontFace: "Georgia",
    color: "FFFFFF", bold: true, align: "left",
    lineSpacingMultiple: 1.1
  });

  // Subtitle question
  slide.addText("How Far Have We Come?", {
    x: 0.5, y: 2.9, w: 5.4, h: 0.6,
    fontSize: 28, fontFace: "Georgia",
    color: theme.light, italic: true, align: "left"
  });

  // Description
  slide.addText("A data-driven overview of renewable energy’s growing share in the global energy and electricity mix, spanning hydropower, wind, and solar technologies.", {
    x: 0.5, y: 3.7, w: 5.2, h: 1.0,
    fontSize: 14, fontFace: "Calibri",
    color: "dad7cd", align: "left", lineSpacingMultiple: 1.3
  });

  // Source attribution
  slide.addText("Source: Our World in Data — Renewable Energy\nData: Ember (2026); Energy Institute (2025)", {
    x: 0.5, y: 4.9, w: 5.0, h: 0.5,
    fontSize: 11, fontFace: "Calibri",
    color: theme.light, align: "left"
  });

  // Decorative circles on right side
  slide.addShape(pres.shapes.OVAL, {
    x: 7.0, y: 0.5, w: 2.5, h: 2.5,
    fill: { color: theme.secondary, transparency: 60 }
  });
  slide.addShape(pres.shapes.OVAL, {
    x: 6.6, y: 2.5, w: 2.0, h: 2.0,
    fill: { color: "588157", transparency: 50 }
  });

  // Key stat callout on right
  slide.addText("~30%", {
    x: 6.4, y: 3.2, w: 3.2, h: 0.9,
    fontSize: 60, fontFace: "Georgia",
    color: "FFFFFF", bold: true, align: "center",
    fit: "shrink"
  });
  slide.addText("of global electricity\nnow from renewables", {
    x: 6.4, y: 4.1, w: 3.2, h: 0.7,
    fontSize: 13, fontFace: "Calibri",
    color: "FFFFFF", align: "center", lineSpacingMultiple: 1.2
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "344e41", secondary: "3a5a40", accent: "588157", light: "a3b18a", bg: "dad7cd" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-01-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

