const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 2,
  title: '75% of Global GHG Emissions Still Come from Fossil Fuels'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("75% of Global GHG Emissions\nStill Come from Fossil Fuels", {
    x: 0.5, y: 0.3, w: 9.0, h: 1.0,
    fontSize: 30, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left",
    lineSpacingMultiple: 1.05, fit: "shrink"
  });

  // Top accent bar under title
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.35, w: 2.0, h: 0.05,
    fill: { color: theme.accent }
  });

  // Context text
  slide.addText("Since the Industrial Revolution, fossil fuels have dominated the global energy system. The consequences are clear — and urgent.", {
    x: 0.5, y: 1.55, w: 9.0, h: 0.5,
    fontSize: 14, fontFace: "Calibri",
    color: theme.secondary, align: "left"
  });

  // Three stat cards
  const cardData = [
    { stat: "75%", label: "of global greenhouse gas\nemissions from fossil fuels", color: theme.primary },
    { stat: "5M+", label: "premature deaths per year\nfrom air pollution", color: theme.accent },
    { stat: "170+", label: "years of fossil fuel\ndominance since Industrial Revolution", color: theme.secondary }
  ];

  const cardW = 2.7;
  const cardH = 2.4;
  const startX = 0.5;
  const gap = 0.35;
  const cardY = 2.3;

  cardData.forEach((d, i) => {
    const cx = startX + i * (cardW + gap);

    // Card background
    slide.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: cardY, w: cardW, h: cardH,
      fill: { color: "FFFFFF" },
      shadow: { type: "outer", blur: 6, offset: 2, angle: 135, color: "000000", opacity: 0.1 }
    });

    // Accent top bar
    slide.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: cardY, w: cardW, h: 0.06,
      fill: { color: d.color }
    });

    // Stat number
    slide.addText(d.stat, {
      x: cx, y: cardY + 0.3, w: cardW, h: 0.9,
      fontSize: 48, fontFace: "Georgia",
      color: d.color, bold: true, align: "center",
      fit: "shrink"
    });

    // Label
    slide.addText(d.label, {
      x: cx + 0.2, y: cardY + 1.3, w: cardW - 0.4, h: 0.9,
      fontSize: 13, fontFace: "Calibri",
      color: theme.secondary, align: "center", lineSpacingMultiple: 1.3
    });
  });

  // Bottom callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.95, w: 9.0, h: 0.45,
    fill: { color: theme.primary }
  });
  slide.addText("To reduce CO₂ emissions and air pollution, the world must rapidly shift toward low-carbon sources — nuclear and renewable technologies.", {
    x: 0.7, y: 4.95, w: 8.6, h: 0.45,
    fontSize: 12, fontFace: "Calibri",
    color: "FFFFFF", align: "left", valign: "middle"
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("2", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "344e41", secondary: "3a5a40", accent: "588157", light: "a3b18a", bg: "dad7cd" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-02-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

