  slide.addText("Approximately one-seventh of the world’s primary energy now comes from renewable technologies (2024 data, substitution method).", {
    x: 0.5, y: 1.15, w: 4.0, h: 0.7,
    fontSize: 14, fontFace: "Calibri",
    color: theme.secondary, align: "left", lineSpacingMultiple: 1.3
  });

