  });

  // Map caption
  slide.addText("Share of primary energy from renewables by country, 2024", {
    x: 4.7, y: 4.55, w: 5.1, h: 0.3,
    fontSize: 10, fontFace: "Calibri",
    color: theme.secondary, align: "center"
  });

