  slide.background = { color: theme.bg };

  // Title
  slide.addText("Renewable Electricity Generation Is Growing Rapidly, Led by Wind and Solar", {
    x: 0.5, y: 0.3, w: 9.0, h: 0.6,
    fontSize: 24, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left", fit: "shrink"
  });

  // Accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 0.95, w: 1.5, h: 0.05,
    fill: { color: theme.accent }
  });

  // Bar chart - Renewable electricity generation by technology
  const chartData = [
    {
      name: "Generation (TWh)",
      labels: ["Hydropower", "Wind", "Solar", "Other Renewables"],
      values: [4500, 2400, 2000, 700]
    }
  ];

  slide.addChart(pres.charts.BAR, chartData, {
    x: 0.5, y: 1.15, w: 5.5, h: 3.2,
    barDir: "col",
    chartColors: [theme.primary, theme.accent, theme.light, theme.secondary],
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: theme.primary,
    dataLabelFontSize: 11,
    dataLabelFontFace: "Calibri",
    catAxisLabelColor: theme.secondary,
    catAxisLabelFontSize: 11,
    catAxisLabelFontFace: "Calibri",
    valAxisLabelColor: theme.secondary,
    valAxisLabelFontSize: 9,
    valGridLine: { color: "dad7cd", size: 0.5 },
    catGridLine: { style: "none" },
    showLegend: false,
    showTitle: false,
    valAxisMinVal: 0,
    valAxisMaxVal: 5000
  });

