    x: 6.3, y: 1.15, w: 3.4, h: 3.2,
    fill: { color: "FFFFFF" },
    shadow: { type: "outer", blur: 4, offset: 2, angle: 135, color: "000000", opacity: 0.08 }
  });

  // Accent bar on card
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.3, y: 1.15, w: 0.06, h: 3.2,
    fill: { color: theme.accent }
