  slide.addText("Technology Breakdown\n(2024 Generation)", {
    x: 6.55, y: 1.25, w: 3.0, h: 0.55,
    fontSize: 14, fontFace: "Georgia",
    color: theme.primary, bold: true, lineSpacingMultiple: 1.1
  });

  // Mini data table
  const tableRows = [
    [
      { text: "Technology", options: { bold: true, fontSize: 10, fontFace: "Calibri", color: "FFFFFF", fill: { color: theme.primary } } },
      { text: "TWh", options: { bold: true, fontSize: 10, fontFace: "Calibri", color: "FFFFFF", fill: { color: theme.primary }, align: "right" } },
      { text: "Share", options: { bold: true, fontSize: 10, fontFace: "Calibri", color: "FFFFFF", fill: { color: theme.primary }, align: "right" } }
    ],
    [
      { text: "Hydropower", options: { fontSize: 10, fontFace: "Calibri", color: theme.secondary } },
      { text: "~4,500", options: { fontSize: 10, fontFace: "Calibri", color: theme.secondary, align: "right" } },
      { text: "~47%", options: { fontSize: 10, fontFace: "Calibri", color: theme.secondary, align: "right" } }
    ],
    [
      { text: "Wind", options: { fontSize: 10, fontFace: "Calibri", color: theme.secondary } },
      { text: "~2,400", options: { fontSize: 10, fontFace: "Calibri", color: theme.secondary, align: "right" } },
      { text: "~25%", options: { fontSize: 10, fontFace: "Calibri", color: theme.secondary, align: "right" } }
    ],
    [
      { text: "Solar", options: { fontSize: 10, fontFace: "Calibri", color: theme.secondary } },
      { text: "~2,000", options: { fontSize: 10, fontFace: "Calibri", color: theme.secondary, align: "right" } },
      { text: "~21%", options: { fontSize: 10, fontFace: "Calibri", color: theme.secondary, align: "right" } }
    ],
    [
      { text: "Other", options: { fontSize: 10, fontFace: "Calibri", color: theme.secondary } },
      { text: "~700", options: { fontSize: 10, fontFace: "Calibri", color: theme.secondary, align: "right" } },
      { text: "~7%", options: { fontSize: 10, fontFace: "Calibri", color: theme.secondary, align: "right" } }
    ]
  ];

  slide.addTable(tableRows, {
    x: 6.5, y: 1.95, w: 3.0,
    border: { pt: 0.5, color: theme.light },
    colW: [1.3, 0.85, 0.85],
    rowH: [0.3, 0.28, 0.28, 0.28, 0.28]
  });

  // Key insight
  slide.addText("Wind and solar combined now nearly match hydropower’s output and are growing much faster.", {
    x: 6.55, y: 3.6, w: 3.0, h: 0.6,
    fontSize: 11, fontFace: "Calibri",
    color: theme.accent, italic: true, lineSpacingMultiple: 1.3
  });

  // Bottom context
