    color: theme.secondary, align: "left"
  });

  slide.addText("Source: Ember (2026); Energy Institute (2025)", {
    x: 0.5, y: 4.95, w: 5.0, h: 0.25,
    fontSize: 9, fontFace: "Calibri",
    color: theme.light
  });

