};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("Hydropower Remains the Largest Renewable Source\nat ~50% of Generation", {
    x: 0.5, y: 0.3, w: 9.0, h: 0.8,
    fontSize: 26, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left", fit: "shrink",
    lineSpacingMultiple: 1.05
  });

  // Accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.15, w: 1.5, h: 0.05,
    fill: { color: theme.accent }
  });

  // Left: map image
  slide.addImage({
    path: "./imgs/figure_6.jpg",
    x: 0.3, y: 1.35, w: 5.5, h: 3.0,
    sizing: { type: "contain", w: 5.5, h: 3.0 }
  });

  // Map caption
  slide.addText("Hydropower generation by country, 2025", {
    x: 0.3, y: 4.4, w: 5.5, h: 0.25,
    fontSize: 10, fontFace: "Calibri",
    color: theme.secondary, align: "center"
  });

  // Right column: key facts
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.0, y: 1.35, w: 3.7, h: 3.0,
