  // Big stat
  slide.addText("~50%", {
    x: 6.3, y: 1.5, w: 3.2, h: 0.8,
    fontSize: 48, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "center",
    fit: "shrink"
  });

  slide.addText("of all renewable electricity\ngeneration comes from hydropower", {
    x: 6.3, y: 2.3, w: 3.2, h: 0.5,
